	// AdminListBrands All brands
	// (GET /admin/brands)
	AdminListBrands(c *gin.Context)
	// AdminCreateBrand Add a brand
	// (POST /admin/brands)
	AdminCreateBrand(c *gin.Context)
	// AdminDeleteBrand Delete a brand with no products (OWNER only)
